<script setup>
import { computed, onMounted, ref, watch } from 'vue'
const key='zoocare_staff', items=ref([]), search=ref(''), showForm=ref(false), editing=ref(null), message=ref('')
const empty=()=>({name:'',role:'Keeper',contact:'',shift:'Day'}), form=ref(empty())
onMounted(()=>items.value=JSON.parse(localStorage.getItem(key)||'[]'))
watch(items,v=>localStorage.setItem(key,JSON.stringify(v)),{deep:true})
const filtered=computed(()=>items.value.filter(v=>[v.name,v.role,v.contact,v.shift].join(' ').toLowerCase().includes(search.value.toLowerCase())))
function openAdd(){editing.value=null;form.value=empty();showForm.value=true;message.value=''}
function edit(v){editing.value=v.id;form.value={...v};showForm.value=true;message.value=''}
function save(){if(!form.value.name.trim()||!form.value.role.trim()){message.value='Staff name and role are required.';return}if(editing.value!==null){const i=items.value.findIndex(v=>v.id===editing.value);items.value[i]={...form.value,name:form.value.name.trim()}}else items.value.push({...form.value,id:Date.now(),name:form.value.name.trim()});showForm.value=false;message.value='Staff member saved successfully.'}
function remove(id){if(confirm('Delete this staff member?'))items.value=items.value.filter(v=>v.id!==id)}
</script>
<template><div class="page-title-row"><div><p class="eyebrow">TEAM DIRECTORY</p><h1>Zoo Staff</h1><p class="muted">Maintain staff names, assigned roles, and contact information.</p></div><button class="btn btn-primary" @click="openAdd">+ Add staff member</button></div><div class="toolbar"><input v-model="search" class="search-input" placeholder="Search name, role, contact, or shift..."><span class="result-count">{{ filtered.length }} staff members</span></div><div v-if="showForm" class="form-panel"><div class="panel-heading"><h2>{{ editing!==null?'Edit staff member':'Add staff member' }}</h2><button class="icon-button" @click="showForm=false">Close</button></div><form @submit.prevent="save" class="form-grid"><label>Full name<input v-model="form.name" placeholder="Full name" required></label><label>Role<select v-model="form.role"><option>Keeper</option><option>Veterinarian</option><option>Administrator</option><option>Maintenance</option></select></label><label>Contact number<input v-model="form.contact" placeholder="Contact number"></label><label>Shift<select v-model="form.shift"><option>Day</option><option>Night</option><option>Rotating</option></select></label><div class="form-actions"><button class="btn btn-primary" type="submit">Save staff member</button><span class="form-message">{{ message }}</span></div></form></div><div class="table-card"><table><thead><tr><th>NAME</th><th>ROLE</th><th>CONTACT</th><th>SHIFT</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="v in filtered" :key="v.id"><td><strong>{{ v.name }}</strong></td><td>{{ v.role }}</td><td>{{ v.contact||'—' }}</td><td>{{ v.shift }}</td><td><div class="actions"><button class="action-link" @click="edit(v)">Edit</button><button class="action-link danger" @click="remove(v.id)">Delete</button></div></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty-state">No staff found. Add a staff member to get started.</td></tr></tbody></table></div></template>
